import hashlib, json

def digest(record):
    raw = json.dumps(record, sort_keys=True).encode()
    return hashlib.sha256(raw).hexdigest()

first = {'prev': 'GENESIS', 'data': 'A pays B'}
second = {'prev': digest(first), 'data': 'B pays C'}
print(second['prev'] == digest(first))

balance = {'alice': 10, 'bob': 0}
def transfer(amount):
    if amount <= 0 or balance['alice'] < amount:
        return False
    balance['alice'] -= amount
    balance['bob'] += amount
    return True
print(transfer(4), balance)

def calculator(a, b, operation):
    if operation not in {'add', 'multiply'}:
        raise ValueError('Unsupported operation')
    return a + b if operation == 'add' else a * b

request = {'a': 8, 'b': 7, 'operation': 'multiply'}
print(calculator(**request))

